(()=>{const out=[];const W=innerWidth;
for(const el of document.querySelectorAll('body *')){const r=el.getBoundingClientRect();if(!r.width||!r.height||r.bottom<0||r.top>innerHeight)continue;
let skryty=false;for(let p=el;p;p=p.parentElement){const c=getComputedStyle(p);if(c.visibility==='hidden'||c.opacity==='0'||p.hidden){skryty=true;break}}if(skryty)continue;
const cs=getComputedStyle(el);const jm=(el.className&&typeof el.className==='string'?'.'+el.className.trim().split(/\s+/).slice(0,2).join('.'):el.tagName.toLowerCase());
if(r.left<W&&r.right>W+1&&el.tagName!=='IMG'&&!/rozmazan|banner-foto/.test(jm))out.push('ZA OKNEM '+jm+' '+Math.round(r.right));
else if(el.children.length===0&&el.scrollWidth>el.clientWidth+2&&cs.overflowX!=='visible'&&cs.textOverflow!=='ellipsis'&&el.textContent.trim())out.push('USEKNUTO '+jm+' „'+el.textContent.trim().slice(0,40)+'“');}
return JSON.stringify([...new Set(out)].slice(0,25));})()

